import React, { useState, useContext } from "react";
import { GlobalContext } from "../context/GlobalState";
import styled, { keyframes, css } from "styled-components";

// Advanced animations
const fadeIn = keyframes`
  from {
    opacity: 0;
    transform: translateY(20px) rotateX(-15deg);
  }
  to {
    opacity: 1;
    transform: translateY(0) rotateX(0);
  }
`;

const pulse = keyframes`
  0% {
    transform: scale(1);
    box-shadow: 0 0 0 0 rgba(74, 124, 255, 0.7);
  }
  70% {
    transform: scale(1.02);
    box-shadow: 0 0 0 12px rgba(74, 124, 255, 0);
  }
  100% {
    transform: scale(1);
    box-shadow: 0 0 0 0 rgba(74, 124, 255, 0);
  }
`;

const float = keyframes`
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-5px);
  }
`;

// CSS variables for theming
const theme = {
  primary: "#4a7cff",
  secondary: "#4ad2ff",
  dark: "#1a1a2e",
  light: "#f5f5f5",
  success: "#4caf50",
  error: "#f44336",
  glass: "rgba(255, 255, 255, 0.15)",
  glassBorder: "rgba(255, 255, 255, 0.3)",
  glassShadow: "0 8px 32px rgba(0, 0, 0, 0.1)",
};

// Glass morphism container
const Container = styled.div`
  background: ${theme.glass};
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-radius: 16px;
  border: 1px solid ${theme.glassBorder};
  padding: 2rem;
  margin: 1.5rem 0;
  box-shadow: ${theme.glassShadow};
  animation: ${fadeIn} 0.8s cubic-bezier(0.23, 1, 0.32, 1) forwards;
  transform-style: preserve-3d;
  perspective: 1000px;
  transition: all 0.5s ease;
  position: relative;
  overflow: hidden;
  z-index: 1;

  &:hover {
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.15);
    transform: translateY(-3px) scale(1.005);
  }

  &::before {
    content: "";
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: linear-gradient(
      45deg,
      transparent,
      rgba(255, 255, 255, 0.1),
      transparent
    );
    transform: rotate(45deg);
    z-index: -1;
    transition: all 0.6s ease;
    opacity: 0;
  }

  &:hover::before {
    opacity: 1;
    animation: ${float} 6s ease-in-out infinite;
  }
`;

// Animated title with gradient text
const Title = styled.h3`
  color: transparent;
  margin-bottom: 1.8rem;
  font-size: 1.6rem;
  font-weight: 700;
  background: linear-gradient(90deg, ${theme.primary}, ${theme.secondary});
  -webkit-background-clip: text;
  background-clip: text;
  position: relative;
  padding-bottom: 0.8rem;
  text-align: center;
  letter-spacing: 0.5px;

  &::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 80px;
    height: 4px;
    background: linear-gradient(90deg, ${theme.primary}, ${theme.secondary});
    border-radius: 4px;
    transition: all 0.4s ease;
  }

  &:hover::after {
    width: 120px;
    background: linear-gradient(90deg, ${theme.secondary}, ${theme.primary});
  }
`;

// 3D transformed form
const Form = styled.form`
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  transform-style: preserve-3d;
`;

// Advanced input with gradient border
const Input = styled.input`
  padding: 1rem 1.2rem;
  border: none;
  border-radius: 10px;
  font-size: 1rem;
  transition: all 0.4s ease;
  outline: none;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
  position: relative;
  z-index: 1;

  &::placeholder {
    color: #a0a0a0;
    transition: all 0.3s ease;
  }

  &:focus {
    background: rgba(255, 255, 255, 1);
    box-shadow: 0 6px 12px rgba(0, 0, 0, 0.1);
    transform: translateY(-2px);

    &::placeholder {
      opacity: 0.5;
      transform: translateX(5px);
    }
  }

  /* Gradient border effect */
  &::before {
    content: "";
    position: absolute;
    top: -2px;
    left: -2px;
    right: -2px;
    bottom: -2px;
    background: linear-gradient(135deg, ${theme.primary}, ${theme.secondary});
    border-radius: 12px;
    z-index: -1;
    opacity: 0;
    transition: all 0.4s ease;
  }

  &:focus::before {
    opacity: 1;
    animation: ${pulse} 2s infinite;
  }
`;

// Advanced button with 3D effect
const Button = styled.button`
  background: linear-gradient(135deg, ${theme.primary}, ${theme.secondary});
  color: white;
  border: none;
  padding: 1rem;
  border-radius: 10px;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  position: relative;
  overflow: hidden;
  z-index: 1;
  text-transform: uppercase;
  letter-spacing: 1px;
  box-shadow: 0 5px 15px rgba(74, 124, 255, 0.4);

  &:hover {
    transform: translateY(-3px) scale(1.02);
    box-shadow: 0 8px 25px rgba(74, 124, 255, 0.6);
  }

  &:active {
    transform: translateY(1px) scale(0.98);
  }

  &:disabled {
    background: #cccccc;
    cursor: not-allowed;
    transform: none;
    box-shadow: none;
  }

  /* Ripple effect */
  &::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 5px;
    height: 5px;
    background: rgba(255, 255, 255, 0.5);
    opacity: 0;
    border-radius: 100%;
    transform: scale(1, 1) translate(-50%);
    transform-origin: 50% 50%;
  }

  &:focus:not(:active)::after {
    animation: ripple 1s ease-out;
  }

  @keyframes ripple {
    0% {
      transform: scale(0, 0);
      opacity: 0.5;
    }
    100% {
      transform: scale(20, 20);
      opacity: 0;
    }
  }
`;

// Floating label effect (optional enhancement)
const InputContainer = styled.div`
  position: relative;
  margin-bottom: 1rem;
`;

const FloatingLabel = styled.label`
  position: absolute;
  pointer-events: none;
  left: 1.2rem;
  top: 1rem;
  transition: all 0.3s ease;
  background: white;
  padding: 0 0.3rem;
  color: #a0a0a0;
  font-size: 1rem;

  ${Input}:focus ~ &,
  ${Input}:not(:placeholder-shown) ~ & {
    top: -0.6rem;
    left: 0.8rem;
    font-size: 0.8rem;
    color: ${theme.primary};
    background: linear-gradient(to bottom, white 50%, transparent 50%);
  }
`;

const AddTransaction = () => {
  const { addTransaction } = useContext(GlobalContext);
  const [text, setText] = useState("");
  const [amount, setAmount] = useState("");

  const onSubmit = (e) => {
    e.preventDefault();

    if (!text || !amount) {
      alert("Please enter text and amount!");
      return;
    }

    const newTransaction = {
      id: Math.floor(Math.random() * 100000),
      text,
      amount: +amount,
    };

    addTransaction(newTransaction);
    setText("");
    setAmount("");
  };

  return (
    <Container>
      <Title>Add New Transaction</Title>
      <Form onSubmit={onSubmit}>
        <InputContainer>
          <Input
            type="text"
            placeholder=" "
            value={text}
            onChange={(e) => setText(e.target.value)}
          />
          <FloatingLabel>Description</FloatingLabel>
        </InputContainer>
        
        <InputContainer>
          <Input
            type="number"
            placeholder=" "
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
          />
          <FloatingLabel>Amount</FloatingLabel>
        </InputContainer>
        
        <Button type="submit" disabled={!text || !amount}>
          Add Transaction
        </Button>
      </Form>
    </Container>
  );
};

export default AddTransaction;
